      var myShare=(a.shares&&a.shares.me!==undefined)?Number(a.shares.me):(Number(a.amount)||0)/Math.max(1,(project.participants||[]).filter(function(p){return p.status!=="archived";}).length||1);
      return{id:"share_"+project.id+"_"+a.id,amount:myShare,catId:"share",methodId:null,desc:(project.name||"Share")+" · "+(a.desc||"Spesa condivisa")+(paidBy?" · pagata da "+paidBy.name:""),date:a.date,createdAt:a.createdAt||a.date,rateizzato:false,rate:1,_share:true,_shareProjectId:project.id,_shareProjectName:project.name,_shareProjectColor:project.color||"#4F8FF7",_shareProjectIcon:project.icon||"🤝",_sharePaidBy:paidBy?paidBy.name:""};
